#!/usr/bin/env python3
"""Render docs/audio/AUDIO_ASSET_MANIFEST.md from public/audio/manifest.json (run after build_all.py)."""
import json
from pathlib import Path

IMPL = Path(__file__).resolve().parent.parent.parent
m = json.loads((IMPL / "public/audio/manifest.json").read_text())
rows = m["assets"]
tot = sum(r["bytes"] for r in rows)
by = {}
for r in rows:
    by.setdefault(r["kind"], []).append(r)
out = ["# Audio asset manifest (generated)", "",
       "Generated by `tools/audio-gen/make_manifest_md.py` from `public/audio/manifest.json`. Do not edit by hand.", "",
       f"- Assets: **{len(rows)}**, total **{tot/1024:.0f} KiB** ({tot/1048576:.2f} MiB), Opus in Ogg, 48 kHz.",
       "- Licence of every asset: original synthesis by this repository's scripts (`tools/audio-gen`, numpy/scipy). No third-party sample, recording, preset or AI audio model. Distributed under the repository licence (GNU AGPL-3.0, see `LICENSE.md`). No attribution is required by any third party.",
       "- Provenance: each row's `source` is the generator function; assets are deterministic (same seed -> same decoded samples; the Ogg serial number differs per encode, so file hashes differ between rebuilds while samples do not).",
       "- Loudness: `LUFS` is ffmpeg ebur128 integrated loudness; clips shorter than ~0.4 s read -70 (gating window): use peak for those. `TP` = true peak dBFS.", ""]
for kind in ("music", "stinger", "amb", "sfxloop", "sfx"):
    rs = by.get(kind, [])
    if not rs:
        continue
    out += [f"## {kind} ({len(rs)}, {sum(r['bytes'] for r in rs)/1024:.0f} KiB)", "", "| id | file | group | bus | dur s | bytes | LUFS | TP dB | sha256 (first 12) | QA |", "|---|---|---|---|---:|---:|---:|---:|---|---|"]
    for r in rs:
        out.append(f"| `{r['id']}` | `{r['file']}` | {r['group']} | {r['bus']} | {r['duration']:.2f} | {r['bytes']} | {r['lufsI']} | {r['truePeakDb']} | `{r['sha256'][:12]}` | {'; '.join(r['qa']) or 'clean'} |")
    out.append("")
out += ["## Open items", "- Subjective quality: NOT_TESTED (no listening). Objective QA only (clipping, DC, latency, tail decay, spectral harshness, loop seam).", "- Safari/iOS decoding of Opus-in-Ogg: NOT_TESTED.", ""]
(IMPL / "docs/audio/AUDIO_ASSET_MANIFEST.md").write_text("\n".join(out))
print("wrote", len(rows), "rows")
